// Lucide icon sprite helpers (fleet D2). Pure at import time: no `document` access until icon() runs.
// The sprite is public/vendor/lucide/sprite.svg, generated by scripts/build-sprite.mjs from
// scripts/icons.json; ICONS mirrors that table's concept names (test/icons.test.mjs keeps them in sync).

export const SPRITE = '/vendor/lucide/sprite.svg';
const SVGNS = 'http://www.w3.org/2000/svg';

export const ICONS = Object.freeze([
  'map', 'board', 'inbox', 'packages', 'audit', 'credit', 'box', 'builder', 'builder-down', 'morning',
  'lane', 'branch', 'pr', 'pr-draft', 'pr-merged', 'ci-pass', 'ci-fail', 'ci-running', 'ci-none',
  's-permission', 's-question', 's-working', 's-done', 's-idle', 's-shell', 's-dead',
  'pause', 'play', 'resume', 'kill', 'restart', 'interrupt', 'approve', 'deny', 'close', 'approval',
  'broadcast', 'stuck', 'budget', 'conflict', 'blocked', 'review', 'ack', 'alarm', 'bell',
  'terminal', 'send', 'pin', 'spawn', 'retire', 'search', 'command', 'filter', 'split',
  'rail', 'inspector', 'chev-r', 'chev-l', 'chev-d', 'keyboard', 'clock', 'cpu', 'mem', 'disk',
  'offline', 'theme', 'external', 'more',
]);

const KNOWN = new Set(ICONS);
const SIZES = new Set(['s', 'm', 'l']);
const FALLBACK = 'alarm';
const warned = new Set();

// Map any input to a known concept; unknown names warn once and fall back (never throw in render).
export function iconName(name) {
  const n = String(name ?? '');
  if (KNOWN.has(n)) return n;
  if (!warned.has(n)) {
    warned.add(n);
    console.warn(`icons: unknown icon ${JSON.stringify(n.slice(0, 40))}, using '${FALLBACK}'`);
  }
  return FALLBACK;
}

function classes(size, cls) {
  const s = SIZES.has(size) ? size : 'm';
  const extra = String(cls ?? '').split(/\s+/).filter((c) => /^[A-Za-z0-9_-]+$/.test(c));
  return ['i', `i-${s}`, ...extra].join(' ');
}

// -> SVGSVGElement: <svg class="i i-m cls" aria-hidden="true" focusable="false"><use href="…#i-name"/></svg>
// With a label: role="img", aria-label, <title> first child, no aria-hidden. Built with DOM APIs only;
// the label goes in via setAttribute/textContent, so builder-provided text is never parsed as markup.
export function icon(name, { size = 'm', label = null, cls = '' } = {}) {
  const id = iconName(name);
  const svg = document.createElementNS(SVGNS, 'svg');
  svg.setAttribute('class', classes(size, cls));
  svg.setAttribute('focusable', 'false');
  if (label != null && String(label) !== '') {
    const text = String(label);
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', text);
    const title = document.createElementNS(SVGNS, 'title');
    title.textContent = text;
    svg.appendChild(title);
  } else {
    svg.setAttribute('aria-hidden', 'true');
  }
  const use = document.createElementNS(SVGNS, 'use');
  use.setAttribute('href', `${SPRITE}#i-${id}`);
  svg.appendChild(use);
  return svg;
}

// String form, for the static kit page only; never used with builder data. The name is
// reduced to a known concept, so the output contains only fixed markup.
export function iconMarkup(name) {
  const id = iconName(name);
  return `<svg class="i i-m" aria-hidden="true" focusable="false"><use href="${SPRITE}#i-${id}"/></svg>`;
}
